"""Provide the owned CODE-EVAL-004 shield_token fixture."""

import logging

logger = logging.getLogger(__name__)


def shield_token(token, keep):
    """Keep only a proper positive suffix; replace every earlier character with #. Mask all characters when keep is nonpositive or at least the token length."""
    logger.info("ce004_fixture_called function=shield_token")
    if keep <= 0 or keep >= len(token):
        return "#" * len(token)
    return "#" * (len(token)-keep) + token[-keep:]

"""Provide the owned CODE-EVAL-004 safe_position fixture."""

import logging

logger = logging.getLogger(__name__)


def safe_position(position, length):
    """Clamp position into inclusive range 0 through length-1. Nonpositive length raises ValueError."""
    logger.info("ce004_fixture_called function=safe_position")
    if length <= 0:
        raise ValueError("empty length")
    return max(0,min(position,length-1))
